import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
public class Main {static class Account implements Serializable{private static final long serialVersionUID=1L;String number,name;long balance;Account(String n,String name,long b){number=n;this.name=name;balance=b;}void deposit(long a){if(a>0)balance+=a;}boolean withdraw(long a){if(a>0&&a<=balance){balance-=a;return true;}return false;}public String toString(){return number+" | "+name+" | Balance="+balance;}}
static void append(Path p,String line)throws IOException{Files.createDirectories(p.getParent());Files.writeString(p,line+System.lineSeparator(),StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.APPEND);}
public static void main(String[] args)throws Exception{Path data=Path.of("data"),accounts=data.resolve("accounts.dat"),logs=data.resolve("logs/transactions.log");Account[] a={new Account("AC0001","Aarav Shah",5000),new Account("AC0002","Diya Patel",3000),new Account("AC0003","Rohan Mehta",7000)};try(ObjectOutputStream out=new ObjectOutputStream(Files.newOutputStream(accounts))){out.writeObject(a);}try(ObjectInputStream in=new ObjectInputStream(Files.newInputStream(accounts))){for(Account x:(Account[])in.readObject())System.out.println(x);}append(logs,"DEPOSIT AC0001 500");append(logs,"WITHDRAW AC0002 200");long deposits=0,withdrawals=0;for(String line:Files.readAllLines(logs)){String[] p=line.split("\\s+");if(p.length>=3)try{if(p[0].equals("DEPOSIT"))deposits+=Long.parseLong(p[2]);else if(p[0].equals("WITHDRAW"))withdrawals+=Long.parseLong(p[2]);}catch(NumberFormatException ignored){}}String report="MINIBANK END-OF-DAY REPORT\nGenerated: "+LocalDateTime.now()+"\nTotal deposits: "+deposits+"\nTotal withdrawals: "+withdrawals+"\nNet change: "+(deposits-withdrawals);Files.writeString(data.resolve("end_of_day_report.txt"),report);System.out.println(report);}}
